<?php namespace App;
final class Router{private array $routes=[];function get(string $p,callable $h):void{$this->add('GET',$p,$h);}function post(string $p,callable $h):void{$this->add('POST',$p,$h);}private function add($m,$p,$h):void{$this->routes[]=[$m,$p,$h];}function dispatch(string $m,string $uri):void{$path=parse_url($uri,PHP_URL_PATH)?:'/';foreach($this->routes as [$method,$pattern,$handler]){$rx='#^'.preg_replace('#\{([a-z_]+)\}#','(?P<$1>[^/]+)',$pattern).'/?$#';if($method===$m&&preg_match($rx,$path,$matches)){call_user_func_array($handler,array_filter($matches,'is_string',ARRAY_FILTER_USE_KEY));return;}}http_response_code(404);view('404',['title'=>'Halaman tidak ditemukan']);}}
